/* Split: o histórico só informa que o split foi feito e o código da nova reserva (não informa quais passageiros). */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var achados = [], divide = 0;
Sabre.hook('antes', function (t) {
  achados = []; divide = 0;
  var txt = plano(t), re = /SPLIT TO\/(\d{2})(\d{2})\d{2}\/(\d{2}[A-Z]{3}\d{2})\s+([A-Z0-9]{6})\b/g, m, vistos = {};
  while ((m = re.exec(txt))) { if (vistos[m[4]]) continue; vistos[m[4]] = 1; achados.push({ pnr: m[4], hora: m[1] + ':' + m[2], data: m[3] }); }
  divide = (txt.match(/DATA REMOVED DUE TO DIVIDE/g) || []).length;
  return t;
});
Sabre.hook('alertas', function () {
  return achados.map(function (a) {
    return { cls: 'alert-blue', icone: 'info', titulo: 'Split realizado: nova reserva ' + a.pnr,
      desc: 'Split em ' + a.data + ' às ' + a.hora + '. O histórico não informa quais passageiros foram para a nova reserva: abra a reserva ' + a.pnr + ' para conferir.' + (divide ? ' Também há ' + divide + ' registro(s) de dados removidos pela divisão.' : '') };
  });
});

/* XXLD AS NOT TICKETED: segmentos cancelados porque o bilhete não foi pago/emitido. */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var qtd = 0;
Sabre.hook('antes', function (t) { qtd = (plano(t).match(/XXLD AS NOT TICKETED/g) || []).length; return t; });
Sabre.hook('alertas', function () {
  if (!qtd) return [];
  return [{ cls: 'alert-red', icone: 'warn', titulo: 'Segmentos cancelados por falta de pagamento (XXLD AS NOT TICKETED)',
    desc: 'O sistema cancelou segmento(s) porque o bilhete não foi emitido/pago. Avisos no histórico: ' + qtd + '. Se o pagamento já estava feito, pode ser erro operacional do sistema ao derrubar os voos por falta de pagamento. Confira o status dos segmentos antes de qualquer ação.' }];
});

/* ETSYNC SSRTKNX: o cupom do bilhete não casa com o segmento; a emissão ou reemissão vai ter problema. */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var bil = [];
Sabre.hook('antes', function (t) {
  bil = [];
  var re = /ETSYNC SSRTKNX - LOOSE OR NO MATCH FOUND BETWEEN COUPON AND SEGMENT - (\d{13})\/C(\d)/g, m, vistos = {}, txt = plano(t);
  while ((m = re.exec(txt))) { var k = m[1] + 'C' + m[2]; if (!vistos[k]) { vistos[k] = 1; bil.push(m[1] + ' (cupom C' + m[2] + ')'); } }
  return t;
});
Sabre.hook('alertas', function () {
  if (!bil.length) return [];
  return [{ cls: 'alert-yellow', icone: 'ticket', titulo: 'Bilhete com problema: cupom sem correspondência com o segmento (ETSYNC)',
    desc: 'O bilhete vai ter problema na emissão ou reemissão. Bilhete(s): ' + bil.slice(0, 4).join(', ') + (bil.length > 4 ? ' e mais ' + (bil.length - 4) : '') + '.' }];
});

/* SSR WVER ... ERROR CONTACT CENTER: waiver por erro operacional do contact center (a LATAM usa outros tipos de waiver). */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var wv = [], total = 0;
Sabre.hook('antes', function (t) {
  wv = []; total = 0;
  var re = /WVER[^\n]*?EXCP F (\d+) EPR (\d+) AMNT (\d+)[^\n]*?ERROR CONTACT CENTER/g, m, vistos = {}, txt = plano(t);
  while ((m = re.exec(txt))) { total++; if (!vistos[m[1]]) { vistos[m[1]] = 1; wv.push('F ' + m[1] + ' (AMNT ' + m[3] + ' USD)'); } }
  return t;
});
Sabre.hook('alertas', function () {
  if (!wv.length) return [];
  return [{ cls: 'alert-yellow', icone: 'warn', titulo: 'Waiver por erro de contact center (erro operacional)',
    desc: total + ' registro(s) WVER. Referências: ' + wv.slice(0, 4).join(' · ') + (wv.length > 4 ? ' e mais ' + (wv.length - 4) : '') + '. A LATAM também usa outros tipos de waiver; este é o de erro operacional.' }];
});

/* H-TI TS DETECTED: o segmento está casado com o passageiro em outra reserva. */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var qtd = 0;
Sabre.hook('antes', function (t) { qtd = (plano(t).match(/TI TS DETECTED/g) || []).length; return t; });
Sabre.hook('alertas', function () {
  if (!qtd) return [];
  return [{ cls: 'alert-blue', icone: 'info', titulo: 'TI TS detectado: segmento casado com o passageiro em outra reserva',
    desc: 'Aparece ' + qtd + ' vez(es) no histórico. O mesmo segmento e passageiro estão em outra reserva: confira a outra reserva antes de alterar ou cancelar.' }];
});

/* Troca de classe repetida (ex.: Q > K > L). O histórico é lido do mais novo para o mais antigo; a sequência é mostrada da mais antiga para a mais recente. */
/* Prepara o texto: tira o separador ¥, espaços de fim de linha, linhas vazias e junta linhas quebradas (continuação com 3+ espaços). */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }

var voos = [];
Sabre.hook('antes', function (t) {
  voos = [];
  var re = /^AS\s+(?:([A-Z0-9]{2})\s+)?(\d{1,4})([A-Z])\s+(\d{2}[A-Z]{3})\s+([A-Z]{6})/gm, m, mapa = {}, ordem = [], txt = plano(t);
  while ((m = re.exec(txt))) { var k = (m[1] || 'LA') + m[2] + ' ' + m[4] + ' ' + m[5]; if (!mapa[k]) { mapa[k] = []; ordem.push(k); } mapa[k].push(m[3]); }
  ordem.forEach(function (k) {
    var seq = mapa[k].slice().reverse().filter(function (c, i, a) { return i === 0 || c !== a[i - 1]; });
    if (seq.length >= 3) voos.push(k.split(' ').slice(0, 2).join(' ') + ': ' + seq.join(' > '));
  });
  return t;
});
Sabre.hook('fatos', function (f) {
  if (!voos.length) return;
  f.indicios.push({ cls: 'alert-blue', ico: 'info', t: 'Classe trocada várias vezes',
    d: voos.slice(0, 6).join(' · ') + '. Trocar só a classe não dá direito a involuntária. Para reemitir, algumas classes funcionam melhor que outras; com outras companhias costuma-se escolher a Y (padrão da econômica).' });
});

/* Agente aeroportuário: a assinatura começa com o código IATA da cidade onde o agente trabalha.
   Ex.: Call Center = QOC5GUJ; o mesmo agente em Porto Alegre = POA5GUJ; em São Paulo = SAO5GUJ (nunca GRU nem CGH).
   A assinatura pode ter ponto (ex.: BSB8C.Z). Só vale se as 3 letras forem uma cidade conhecida e
   se nenhuma regra "Quem alterou" já reconhece a assinatura (robôs, Call Center, CPC, site etc.). */
Sabre.hook('ator', function (code, from, station) {
  var c = String(code || '').toUpperCase(), f = String(from || '').toUpperCase();
  var m = c.match(/^([A-Z]{3})(\d)([A-Z0-9.]{2,3})$/);
  if (!m || m[1] === 'HDQ') return;
  var cidade = Sabre.iataFull(m[1]);
  if (!cidade || cidade === m[1]) return;
  var R = (Sabre.regras && Sabre.regras.atores) || [];
  for (var i = 0; i < R.length; i++) {
    var r = R[i];
    if (r.semAssinatura && c) continue;
    if ((r.sigs && r.sigs.some(function (p) { return c.indexOf(p) === 0; })) || (r.textos && r.textos.some(function (p) { return f.indexOf(p) >= 0; }))) return;
  }
  var robos = (Sabre.dicionarios && Sabre.dicionarios.robos) || [];
  if (robos.some(function (x) { return f.indexOf(x) >= 0; })) return;
  return { k: 'aeroporto_' + m[1], rot: 'Agente aeroportuário – ' + cidade, grupo: 'agente', cls: 'b-blue', robo: false,
    desc: 'Assinatura ' + c + ': agente aeroportuário. As 3 primeiras letras são o código IATA da cidade onde ele trabalha (em São Paulo é SAO, não GRU nem CGH).' };
});

/* VOID: o cancelamento cria um ticket virtual (TV) que anula o bilhete emitido. */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }
var v = [];
Sabre.hook('antes', function (t) {
  v = [];
  var re = /TV (\d{13}) \*VOID\*/g, m, vistos = {}, txt = plano(t);
  while ((m = re.exec(txt))) { if (!vistos[m[1]]) { vistos[m[1]] = 1; v.push(m[1]); } }
  return t;
});
Sabre.hook('alertas', function () {
  if (!v.length) return [];
  return [{ cls: 'alert-yellow', icone: 'ticket', titulo: 'Bilhete anulado (VOID)',
    desc: 'O VOID cria um ticket virtual (TV) para anular o bilhete: ' + v.slice(0, 4).join(', ') + (v.length > 4 ? ' e mais ' + (v.length - 4) : '') + '. Confira se o itinerário voltou ao anterior.' }];
});

/* Bebê (INF): só vale até 2 anos. A linha INFT traz a data de nascimento; a idade é conferida na data de cada voo. */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }
var MES = { JAN: 0, FEB: 1, MAR: 2, APR: 3, MAY: 4, JUN: 5, JUL: 6, AUG: 7, SEP: 8, OCT: 9, NOV: 10, DEC: 11 };
var achados = [];
Sabre.hook('antes', function (t) {
  achados = [];
  var txt = plano(t), ref = txt.match(/\/(\d{2})([A-Z]{3})(\d{2})\b/);
  var anoRef = ref ? 2000 + Number(ref[3]) : new Date().getFullYear(), mesRef = ref && MES[ref[2]] != null ? MES[ref[2]] : 0;
  var re = /INFT LA HK1 [A-Z]{6}\d{3,4}[A-Z]?(\d{2})([A-Z]{3})\/([A-Z' ]+\/[A-Z' ]+)\/(\d{2})([A-Z]{3})(\d{2})/g, m, vistos = {};
  while ((m = re.exec(txt))) {
    if (MES[m[2]] == null || MES[m[5]] == null) continue;
    var anoVoo = anoRef + (MES[m[2]] < mesRef ? 1 : 0);
    var voo = new Date(anoVoo, MES[m[2]], Number(m[1])), nasc = new Date(2000 + Number(m[6]), MES[m[5]], Number(m[4]));
    var meses = (voo.getFullYear() - nasc.getFullYear()) * 12 + voo.getMonth() - nasc.getMonth() - (voo.getDate() < nasc.getDate() ? 1 : 0);
    var k = m[3] + m[1] + m[2];
    if (meses >= 24 && !vistos[m[3]]) { vistos[m[3]] = 1; achados.push({ nome: m[3], nasc: m[4] + '/' + ('0' + (MES[m[5]] + 1)).slice(-2) + '/' + (2000 + Number(m[6])), voo: m[1] + m[2], anos: Math.floor(meses / 12), meses: meses % 12 }); }
  }
  return t;
});
Sabre.hook('alertas', function () {
  return achados.map(function (a) {
    return { cls: 'alert-red', icone: 'warn', titulo: 'Bebê (INF) acima do limite de idade',
      desc: a.nome + ' nasceu em ' + a.nasc + ' e terá ' + a.anos + ' anos e ' + a.meses + ' meses no voo de ' + a.voo + '. O INF vale só até 2 anos: confira antes de seguir.' };
  });
});

/* Dados do pagante (NMP/NRP) com o texto-modelo no lugar dos dados reais. */
function plano(t){ return String(t).replace(/\u00a5/g,'').replace(/[ \t]+$/gm,'').replace(/\n\s*\n/g,'\n').replace(/\n {3,}/g,''); }
var f = [];
Sabre.hook('antes', function (t) {
  f = []; var txt = plano(t);
  if (/H-NMP\/NOME PAGANTE/.test(txt)) f.push('nome do pagante (NMP)');
  if (/H-NRP\/CPF\/CNPJ/.test(txt)) f.push('documento do pagante (NRP)');
  return t;
});
Sabre.hook('alertas', function () {
  if (!f.length) return [];
  return [{ cls: 'alert-yellow', icone: 'warn', titulo: 'Dados do pagante com texto-modelo',
    desc: 'Aparece o texto-modelo no lugar dos dados reais: ' + f.join(' e ') + '. O próprio sistema coloca esse texto (motivo desconhecido): os dados do pagante não parecem preenchidos.' }];
});

/* O que o time ainda não sabe explicar não aparece como informação: essas linhas são descartadas
   (OSI YY REFUND100, SSR ENRL e H-MTO.PURCHASER). Para voltar a mostrar, desative este módulo. */
Sabre.hook('linha', function (l) {
  if (/OSI YY REFUND100/.test(l)) return { ignorar: true };
  if (/^[AXU]4S\*?\s+SSR ENRL\b/.test(l)) return { ignorar: true };
  if (/^[AXU]5H\*?\s+H-MTO\.PURCHASER/.test(l)) return { ignorar: true };
});

/* OB: o segmento entra como OB e o sistema confirma depois (alteração no site ou mudança de classe pelo CEPNR). Texto e cor vêm do indício "ob" da aba Regras. */
Sabre.hook('fatos', function (f, ctx) {
  var r = ((Sabre.regras && Sabre.regras.indicios) || []).filter(function (x) { return x.k === 'ob'; })[0];
  if (!r) return;
  var vistos = {};
  ctx.cron.forEach(function (b) {
    b.evs.forEach(function (e) {
      var m = e.meta || {};
      if (m.kind !== 'seg' || m.acao === 'XS' || (m.stOld !== 'OB' && m.stNew !== 'OB')) return;
      var k = m.voo + '|' + m.data + '|' + (b.dt || '');
      if (vistos[k]) return; vistos[k] = 1;
      f.indicios.push({ cls: r.cls, ico: r.icone || 'info', t: r.titulo + ' · ' + m.voo + ' ' + m.data, d: r.desc.replace(/\{dt\}/g, b.dt || '') + ' Quem: ' + ((b.ator && b.ator.rot) || 'não identificado') + '.' });
    });
  });
});

/* LP: assento removido (X4G) com o atributo LP = alterado sem autorização do passageiro. Texto e cor vêm do indício "lp" da aba Regras. */
Sabre.hook('fatos', function (f, ctx) {
  var r = ((Sabre.regras && Sabre.regras.indicios) || []).filter(function (x) { return x.k === 'lp'; })[0];
  if (!r) return;
  var vistos = {};
  ctx.cron.forEach(function (b) {
    b.evs.forEach(function (e) {
      var m = e.meta || {};
      var linhaX = m.kind === 'seatswap' ? String(e.raw || '').split('\n')[0] : (m.kind === 'seat' && m.acao === 'X' ? String(e.raw || '') : null);
      if (linhaX === null || !/\bLP\b/.test(linhaX.split(/\s-[A-Z]/)[0])) return;
      var k = m.voo + '|' + m.data + '|' + (b.dt || '');
      if (vistos[k]) return; vistos[k] = 1;
      f.indicios.push({ cls: r.cls, ico: r.icone || 'info', t: r.titulo + ' · ' + m.voo + ' ' + m.data + ((m.seat || m.de) ? ' (' + (m.seat || m.de) + ')' : ''), d: r.desc.replace(/\{dt\}/g, b.dt || '') + ' Quem: ' + ((b.ator && b.ator.rot) || 'não identificado') + '.' });
    });
  });
});
